<template><view class="page"><nav-bar title="已选题目" :showBack="true" placeholder/><view class="summary">共 {{paper.questionCount||0}} 题　总分 {{paper.totalScore||0}} 分</view><scroll-view scroll-y class="list"><view v-for="(item,index) in paper.questions" :key="item.id" class="card"><view class="top"><text class="order">{{index+1}}</text><text class="type">{{item.question.questionType}}</text><view class="sort"><text @click="move(index,-1)">↑</text><text @click="move(index,1)">↓</text></view></view><text class="content">{{item.question.content}}</text><view class="foot"><view class="score"><input type="number" :value="item.score" @blur="score(item,$event.detail.value)"/><text>分</text></view><text class="remove" @click="remove(item)">移除</text></view></view><view v-if="!paper.questions?.length" class="empty">尚未选择题目</view></scroll-view><view class="bottom"><button class="secondary" @click="backSelect">继续选题</button><button class="primary" @click="preview">预览试卷</button></view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{getPaper,updatePaperQuestion,removePaperQuestion}from'@/api/paper.js';export default{components:{NavBar},data(){return{paperId:null,paper:{questions:[]}}},onLoad(q){this.paperId=q.paperId},onShow(){this.load()},methods:{async load(){const r=await getPaper(this.paperId);this.paper=r.data},async score(item,value){const n=Number(value);if(n<=0){uni.showToast({title:'分值必须大于0',icon:'none'});return this.load()}const r=await updatePaperQuestion(this.paperId,item.questionId,{score:n});this.paper=r.data},async move(i,d){const j=i+d;if(j<0||j>=this.paper.questions.length)return;const a=this.paper.questions[i];const r=await updatePaperQuestion(this.paperId,a.questionId,{questionOrder:j+1});this.paper=r.data;uni.showToast({title:'排序已保存',icon:'none'})},remove(item){uni.showModal({title:'移除题目',content:'确认从试卷中移除这道题？',success:async r=>{if(r.confirm){const x=await removePaperQuestion(this.paperId,item.questionId);this.paper=x.data}}})},backSelect(){uni.navigateBack()},preview(){if(!this.paper.questionCount)return uni.showToast({title:'请至少选择一道题',icon:'none'});uni.navigateTo({url:`/subpackage_ai/paperPreview/paperPreview?paperId=${this.paperId}`})}}}</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f8fc;padding-bottom:120rpx}.summary{margin:20rpx 24rpx;background:#eaf2ff;color:#4269c8;border-radius:18rpx;padding:22rpx;text-align:center;font-weight:600}.list{height:calc(100vh - 250rpx);padding:0 24rpx;box-sizing:border-box}.card{background:#fff;border-radius:18rpx;padding:23rpx;margin-bottom:14rpx}.top{display:flex;align-items:center}.order{width:42rpx;height:42rpx;border-radius:50%;background:#4d78e8;color:#fff;text-align:center;line-height:42rpx}.type{margin-left:12rpx;color:#5774b8;font-size:22rpx}.sort{margin-left:auto}.sort text{padding:10rpx 16rpx;color:#4d78e8}.content{display:block;color:#27364d;font-size:27rpx;line-height:1.6;margin:18rpx 0}.foot{display:flex;justify-content:space-between}.score{display:flex;align-items:center}.score input{width:80rpx;background:#f2f5fa;border-radius:10rpx;text-align:center;padding:8rpx}.remove{color:#e16767}.bottom{position:fixed;bottom:0;left:0;right:0;background:#fff;display:flex;gap:16rpx;padding:16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom))}.bottom button{flex:1;border-radius:40rpx;font-size:26rpx}.secondary{background:#eef3fd;color:#4d78e8}.primary{background:#4d78e8;color:#fff}.empty{text-align:center;color:#9ba6b8;padding:100rpx}</style>
